const payload = $('Execute Workflow Trigger').item.json || {};
const chatId = String(payload.chatId || payload.message?.chat?.id || '').trim();
const summary = String(payload.summary || payload.episode_summary || payload.episodeSummary || '').trim();
const topic = String(payload.topic || 'general').trim() || 'general';
const sourceText = String(payload.rawText || payload.text || summary || '').trim();
const importance = Math.max(1, Math.min(5, Number(payload.importance || 3) || 3));
const tags = Array.isArray(payload.tags)
  ? payload.tags.map((tag) => String(tag || '').trim()).filter(Boolean)
  : String(payload.tags || '')
      .split(',')
      .map((tag) => tag.trim())
      .filter(Boolean);
const escapeSql = (value = '') => String(value || '').replace(/'/g, "''");
if (!chatId) {
  throw new Error('Missing chatId for memory_save_episode');
}
if (!summary) {
  return [{ json: { chatId, skip: true, responseText: 'MEMORY_SAVE_EPISODE_SKIPPED\nreason: empty summary' } }];
}
const tagsSql = `ARRAY[${tags.map((tag) => `'${escapeSql(tag)}'`).join(', ')}]::text[]`;
const insertSql = `INSERT INTO mia_episodes (chat_id, episode_summary, topic, tags, source_text, episode_date, importance, created_at, updated_at) VALUES ('${escapeSql(chatId)}', '${escapeSql(summary)}', '${escapeSql(topic)}', ${tags.length ? tagsSql : 'ARRAY[]::text[]'}, '${escapeSql(sourceText)}', CURRENT_DATE, ${importance}, now(), now()) RETURNING chat_id, episode_summary, topic, tags, importance, updated_at;`;
return [{ json: { chatId, skip: false, summary, topic, tags, importance, insertSql } }];

const source = $('Prepare Episode Input').item.json || {};
if (source.skip) {
  return [{ json: { text: source.responseText, chatId: source.chatId || '' } }];
}
const row = $json || {};
const tags = Array.isArray(row.tags) ? row.tags.filter(Boolean).join(', ') : '';
const parts = [
  'MEMORY_SAVE_EPISODE_OK',
  `topic: ${row.topic || source.topic || 'general'}`,
  `summary: ${row.episode_summary || source.summary || ''}`,
  `importance: ${row.importance || source.importance || 3}`
];
if (tags) parts.push(`tags: ${tags}`);
return [{ json: { text: parts.join('\n'), chatId: row.chat_id || source.chatId || '' } }];
